insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('cc2bad65-7938-4612-9624-26fa5ae2ceaf', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', null, 'topic'::public.curated_course_node_type, 'Managerial Accounting, Hospitality Value Creation, and Ethics', 'Managerial accounting turns financial and nonfinancial evidence into better planning, control, evaluation, and resource-allocation decisions. This opening section establishes the manager''s role as an accountable user and steward of information—not merely a calculator of costs.', 0),
  ('8db506e1-f8a8-4558-9188-ae17488a5921', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'cc2bad65-7938-4612-9624-26fa5ae2ceaf', 'subtopic'::public.curated_course_node_type, 'Managerial versus financial accounting', 'Students learn why internal reports differ from external statements and how decision purpose determines the relevant detail, timing, and format.', 0),
  ('ba003f43-824b-4266-87de-ba95caab522f', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '8db506e1-f8a8-4558-9188-ae17488a5921', 'concept'::public.curated_course_node_type, 'Internal users, operational focus, future orientation, timeliness, detail, and decision relevance', null, 0),
  ('698141d9-4b18-47e1-bc75-441022674ad4', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '8db506e1-f8a8-4558-9188-ae17488a5921', 'concept'::public.curated_course_node_type, 'Relationship to U.S. GAAP-based records, audited statements, tax reporting, and owner or lender requirements', null, 1),
  ('b9ce0bed-7460-4595-8376-321fa2b421d5', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '8db506e1-f8a8-4558-9188-ae17488a5921', 'concept'::public.curated_course_node_type, 'Planning, controlling, evaluating, learning, and communicating across hospitality departments', null, 2),
  ('26183691-8c54-4ad8-a353-ccfa27e433f9', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'cc2bad65-7938-4612-9624-26fa5ae2ceaf', 'subtopic'::public.curated_course_node_type, 'Hospitality business models and value drivers', 'This subtopic links accounting information to the distinctive economics of perishable capacity, high fixed costs, variable demand, and multiple revenue centers.', 1),
  ('0e08f0fa-00bc-4139-b050-efdc1028226f', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '26183691-8c54-4ad8-a353-ccfa27e433f9', 'concept'::public.curated_course_node_type, 'Hotels, resorts, restaurants, clubs, casinos, events, franchises, management companies, and mixed-use assets', null, 0),
  ('fa30bc7c-c320-4af9-bc54-3ec51dfec7d6', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '26183691-8c54-4ad8-a353-ccfa27e433f9', 'concept'::public.curated_course_node_type, 'Ownership, operator, brand, asset manager, landlord, lender, and third-party platform perspectives', null, 1),
  ('5ebec0b0-cda7-4358-8061-ac83b4d26d5c', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '26183691-8c54-4ad8-a353-ccfa27e433f9', 'concept'::public.curated_course_node_type, 'Capacity, occupancy, covers, average checks, rate, mix, labor, quality, loyalty, channel cost, and asset intensity', null, 2),
  ('a412f407-a6a3-4264-903a-31c34855e49d', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'cc2bad65-7938-4612-9624-26fa5ae2ceaf', 'subtopic'::public.curated_course_node_type, 'Ethics and professional judgment', 'Students apply ethical standards when estimates, targets, incentives, and pressure could distort information or behavior.', 2),
  ('896cc339-4fb9-4845-baad-840d55777154', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a412f407-a6a3-4264-903a-31c34855e49d', 'concept'::public.curated_course_node_type, 'IMA principles: honesty, fairness, objectivity, and responsibility', null, 0),
  ('e7cf32e8-986d-48d7-9324-7e9232034135', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a412f407-a6a3-4264-903a-31c34855e49d', 'concept'::public.curated_course_node_type, 'IMA standards: competence, confidentiality, integrity, and credibility', null, 1),
  ('7a537ebe-b4e7-4cc9-a7ee-33dbac89a9c4', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a412f407-a6a3-4264-903a-31c34855e49d', 'concept'::public.curated_course_node_type, 'Budget gaming, earnings manipulation, biased assumptions, omitted risks, data privacy, speaking up, escalation, and documentation', null, 2),
  ('e1579842-456f-4e89-b426-38c3d6a69726', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', null, 'topic'::public.curated_course_node_type, 'Hospitality Account Structures and Departmental Statements', 'Hospitality managers need a shared reporting language to compare departments, properties, periods, budgets, and peers. This section introduces industry account structures while emphasizing that internal reports must remain faithful to underlying transactions and management contracts.', 1),
  ('0a130a7e-b700-4f59-9605-40bf99d51aa1', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'e1579842-456f-4e89-b426-38c3d6a69726', 'subtopic'::public.curated_course_node_type, 'Uniform systems and chart-of-accounts design', 'Students learn how standardized account structures improve consistency without eliminating property-specific managerial detail.', 0),
  ('b54dde0a-e54b-44b1-9827-9e115af94629', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '0a130a7e-b700-4f59-9605-40bf99d51aa1', 'concept'::public.curated_course_node_type, 'Uniform System of Accounts for the Lodging Industry (USALI), 12th Revised Edition, effective January 1, 2026', null, 0),
  ('f0823cc0-de9b-402e-883b-dfa77500123f', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '0a130a7e-b700-4f59-9605-40bf99d51aa1', 'concept'::public.curated_course_node_type, 'Uniform System of Accounts for Restaurants and operation-specific account maps', null, 1),
  ('5451a1e0-4109-4ca4-86db-88dcec93919c', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '0a130a7e-b700-4f59-9605-40bf99d51aa1', 'concept'::public.curated_course_node_type, 'Account codes, dimensions, departments, revenue centers, cost centers, entities, projects, channels, and responsibility owners', null, 2),
  ('f1227d73-0a60-4661-bb3e-8bd4b4399da7', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'e1579842-456f-4e89-b426-38c3d6a69726', 'subtopic'::public.curated_course_node_type, 'Lodging operating statements', 'This subtopic explains how revenues and expenses flow through operated and undistributed departments to property-level results.', 1),
  ('e92f02e6-b7f5-4383-a7ed-515def704acc', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'f1227d73-0a60-4661-bb3e-8bd4b4399da7', 'concept'::public.curated_course_node_type, 'Rooms, food and beverage, other operated departments, miscellaneous income, and departmental profit', null, 0),
  ('325b1f67-6d3a-4ec2-999a-222ec4ea6c69', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'f1227d73-0a60-4661-bb3e-8bd4b4399da7', 'concept'::public.curated_course_node_type, 'Administrative and general, information and telecommunications systems, sales and marketing, property operations and maintenance, and utilities', null, 1),
  ('8f30f6fd-31fa-4601-ba5e-8da6bd2266b3', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'f1227d73-0a60-4661-bb3e-8bd4b4399da7', 'concept'::public.curated_course_node_type, 'Gross operating profit, management fees, non-operating income and expenses, fixed charges, owner items, and reconciliation', null, 2),
  ('cb98aca4-811e-4ba6-820c-3276c762678c', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'e1579842-456f-4e89-b426-38c3d6a69726', 'subtopic'::public.curated_course_node_type, 'Restaurant and multi-outlet statements', 'Students organize sales and costs so chefs, outlet leaders, and general managers can see volume, mix, margin, and accountability.', 2),
  ('86878b6a-13e8-4842-a767-853efc7496a6', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'cb98aca4-811e-4ba6-820c-3276c762678c', 'concept'::public.curated_course_node_type, 'Food, beverage, merchandise, catering, delivery, service charges, discounts, comps, and taxes', null, 0),
  ('629915e6-0c78-470d-9b01-a3e7b83e392e', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'cb98aca4-811e-4ba6-820c-3276c762678c', 'concept'::public.curated_course_node_type, 'Cost of sales, payroll and related costs, controllable operating expenses, occupancy, and corporate allocations', null, 1),
  ('ea0fcd95-1be8-4272-9530-d5bcfa79e7aa', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'cb98aca4-811e-4ba6-820c-3276c762678c', 'concept'::public.curated_course_node_type, 'Single-unit, outlet, daypart, concept, event, location, and consolidated reporting', null, 2),
  ('e3d6fe9b-6d67-44f3-84a5-4e95a11cf074', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', null, 'topic'::public.curated_course_node_type, 'Cost Concepts, Assignment, Behavior, and Estimation', 'A cost has meaning only in relation to a question. Students learn to classify, trace, allocate, and estimate costs so models reflect operational reality rather than convenient labels.', 2),
  ('718690c4-b346-4049-a612-6056cafe0b6b', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'e3d6fe9b-6d67-44f3-84a5-4e95a11cf074', 'subtopic'::public.curated_course_node_type, 'Cost objects and classifications', 'Students identify the guest, room, menu item, outlet, event, channel, department, property, or decision whose economics are being measured.', 0),
  ('a7f52224-0054-4627-b06c-4dfa3e88514c', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '718690c4-b346-4049-a612-6056cafe0b6b', 'concept'::public.curated_course_node_type, 'Direct and indirect; product/service and period; controllable and noncontrollable', null, 0),
  ('07608028-f900-4e8c-bf9f-0d3e669a5dd6', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '718690c4-b346-4049-a612-6056cafe0b6b', 'concept'::public.curated_course_node_type, 'Fixed, variable, mixed, step, committed, discretionary, avoidable, sunk, incremental, and opportunity costs', null, 1),
  ('e716d1a5-768e-4b38-8d95-03076e808c7a', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '718690c4-b346-4049-a612-6056cafe0b6b', 'concept'::public.curated_course_node_type, 'Relevant range, time horizon, capacity level, unit cost, total cost, and allocation purpose', null, 2),
  ('ffe76cab-c439-4479-80c8-2e312d343c0f', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'e3d6fe9b-6d67-44f3-84a5-4e95a11cf074', 'subtopic'::public.curated_course_node_type, 'Cost assignment and allocation', 'This subtopic develops fair, useful methods for assigning shared resources without confusing allocated cost with avoidable cost.', 1),
  ('934ca5ad-c279-4392-87f0-e50659f9ca8c', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'ffe76cab-c439-4479-80c8-2e312d343c0f', 'concept'::public.curated_course_node_type, 'Tracing, allocation, cost pools, cost drivers, reciprocal services, and allocation bases', null, 0),
  ('e7622149-acc2-4f62-b28d-36def8793176', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'ffe76cab-c439-4479-80c8-2e312d343c0f', 'concept'::public.curated_course_node_type, 'Traditional departmental allocation, activity-based costing, time-driven activity-based costing, and capacity cost rates', null, 1),
  ('89228625-5f21-4eb5-9fbb-1fbc1ea64d68', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'ffe76cab-c439-4479-80c8-2e312d343c0f', 'concept'::public.curated_course_node_type, 'Causality, benefits received, ability to bear, simplicity, consistency, incentives, and allocation disputes', null, 2),
  ('dc292872-d93e-46fc-8f09-8ffc4d8bd6de', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'e3d6fe9b-6d67-44f3-84a5-4e95a11cf074', 'subtopic'::public.curated_course_node_type, 'Cost behavior and estimation', 'Students use data and operational knowledge to estimate how costs respond to volume, mix, time, and constraints.', 2),
  ('429f195c-9100-4507-9af3-83f605548de1', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'dc292872-d93e-46fc-8f09-8ffc4d8bd6de', 'concept'::public.curated_course_node_type, 'Account analysis, engineering estimates, scatterplots, high-low method, and regression', null, 0),
  ('fae837e3-433d-4029-a9ce-66f048cd6bce', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'dc292872-d93e-46fc-8f09-8ffc4d8bd6de', 'concept'::public.curated_course_node_type, 'Outliers, seasonality, inflation, structural breaks, nonlinear effects, learning, and capacity steps', null, 1),
  ('edc6001c-c14c-4040-a470-87a101275f19', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'dc292872-d93e-46fc-8f09-8ffc4d8bd6de', 'concept'::public.curated_course_node_type, 'Model fit, residuals, reasonableness, sensitivity, confidence, validation, and update cadence', null, 2),
  ('0079e25f-26a3-43b5-817e-2a08167baa85', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', null, 'topic'::public.curated_course_node_type, 'Contribution Margin, Cost-Volume-Profit, and Profit Planning', 'Contribution analysis shows how price, volume, mix, variable cost, and fixed cost combine to produce profit. Students use it to test operating plans while recognizing that simplified models require clear assumptions.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('a0e68f0f-0f1d-46bb-8f70-4882054b3c9f', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '0079e25f-26a3-43b5-817e-2a08167baa85', 'subtopic'::public.curated_course_node_type, 'Contribution format and unit economics', 'Students reorganize results by cost behavior to reveal the incremental economics of rooms, covers, events, and channels.', 0),
  ('3bdfae29-f89e-4408-9acc-8549630eb196', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a0e68f0f-0f1d-46bb-8f70-4882054b3c9f', 'concept'::public.curated_course_node_type, 'Revenue, variable cost, contribution margin, contribution margin ratio, and traceable fixed cost', null, 0),
  ('aab59c5c-2211-42ba-afb1-0a785811b281', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a0e68f0f-0f1d-46bb-8f70-4882054b3c9f', 'concept'::public.curated_course_node_type, 'Per occupied room, available room, cover, seat-hour, order, event, member, and channel unit economics', null, 1),
  ('92763ff0-e754-4ea8-8d90-5d733bdd352f', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a0e68f0f-0f1d-46bb-8f70-4882054b3c9f', 'concept'::public.curated_course_node_type, 'Gross margin versus contribution margin; service charges, commissions, merchant fees, and incremental labor', null, 2),
  ('14a90dae-ceaf-4c8e-812f-c039981af421', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '0079e25f-26a3-43b5-817e-2a08167baa85', 'subtopic'::public.curated_course_node_type, 'Break-even and target-profit analysis', 'This subtopic translates a profit objective into the sales, occupancy, covers, check average, or room-rate conditions needed to reach it.', 1),
  ('6b723201-0f6b-4774-a2c3-dc166cd17550', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '14a90dae-ceaf-4c8e-812f-c039981af421', 'concept'::public.curated_course_node_type, 'Break-even units and sales dollars; target-profit volume; margin of safety; degree of operating leverage', null, 0),
  ('2c32f9bc-03dc-41d7-a107-13185928bde4', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '14a90dae-ceaf-4c8e-812f-c039981af421', 'concept'::public.curated_course_node_type, 'Single-product, multiproduct, weighted sales mix, composite units, and changing mix', null, 1),
  ('1aa954c1-e58d-4e63-ad24-c8b850168327', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '14a90dae-ceaf-4c8e-812f-c039981af421', 'concept'::public.curated_course_node_type, 'Taxes where relevant, capacity limits, seasonality, step costs, ramp-up, and shutdown points', null, 2),
  ('afecfdbd-eb0e-477f-8590-d401f0d4626e', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '0079e25f-26a3-43b5-817e-2a08167baa85', 'subtopic'::public.curated_course_node_type, 'What-if and sensitivity analysis', 'Students move beyond one-point answers to identify the assumptions that matter and the combinations that threaten or improve the plan.', 2),
  ('03743b69-c09d-4047-a11d-ec17fa56586d', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'afecfdbd-eb0e-477f-8590-d401f0d4626e', 'concept'::public.curated_course_node_type, 'Price-volume-cost tradeoffs, promotions, discounting, wage or food inflation, and channel shifts', null, 0),
  ('01e868e6-a1c5-4eb3-8ff9-83a7950d59cc', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'afecfdbd-eb0e-477f-8590-d401f0d4626e', 'concept'::public.curated_course_node_type, 'One-way and two-way data tables, scenarios, tornado charts, goal seek, and break-even surfaces', null, 1),
  ('905e956c-255e-4b0d-a284-3ed730a702f3', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'afecfdbd-eb0e-477f-8590-d401f0d4626e', 'concept'::public.curated_course_node_type, 'Base, upside, downside, stress, trigger, contingency, and decision thresholds', null, 2),
  ('b3ee96da-e745-4bdf-b9b8-8625803f23fc', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', null, 'topic'::public.curated_course_node_type, 'Budgeting, Forecasting, and Integrated Operating Plans', 'Budgets coordinate strategy, demand, staffing, purchasing, capital, and cash. This section emphasizes driver-based plans that managers can update and act on—not annual numbers created only to satisfy headquarters.', 4),
  ('f668608c-85bf-429f-900a-977f630881b4', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'b3ee96da-e745-4bdf-b9b8-8625803f23fc', 'subtopic'::public.curated_course_node_type, 'Budget architecture and governance', 'Students learn how assumptions, schedules, responsibilities, approvals, and versions combine into a coherent plan.', 0),
  ('3bd93733-e30e-48b2-afbf-1c5f370e05a8', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'f668608c-85bf-429f-900a-977f630881b4', 'concept'::public.curated_course_node_type, 'Strategic plan, annual operating budget, rolling forecast, long-range plan, and capital plan', null, 0),
  ('f4226fbd-ba88-4162-add5-66f3122931aa', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'f668608c-85bf-429f-900a-977f630881b4', 'concept'::public.curated_course_node_type, 'Budget calendar, owners, assumptions book, templates, review meetings, challenge process, and sign-off', null, 1),
  ('305dce6d-52c3-4cb2-a82e-188e3694c58b', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'f668608c-85bf-429f-900a-977f630881b4', 'concept'::public.curated_course_node_type, 'Top-down targets, bottom-up plans, participative budgeting, negotiated goals, slack, and ethics', null, 2),
  ('e6fe2cf1-dbec-4d3f-aabc-1b18f51cc337', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'b3ee96da-e745-4bdf-b9b8-8625803f23fc', 'subtopic'::public.curated_course_node_type, 'Revenue and volume forecasting', 'This subtopic connects market demand and operational capacity to rooms, covers, events, membership, and ancillary revenue.', 1),
  ('8c8605f7-4eda-49f5-9381-57f773f35fac', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'e6fe2cf1-dbec-4d3f-aabc-1b18f51cc337', 'concept'::public.curated_course_node_type, 'Occupancy, ADR, room nights, pace, pickup, cancellations, no-shows, length of stay, and channel mix', null, 0),
  ('7bdd0172-d513-4707-92a6-8e588e8b286e', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'e6fe2cf1-dbec-4d3f-aabc-1b18f51cc337', 'concept'::public.curated_course_node_type, 'Covers, check average, seat turns, dayparts, catering, events, delivery, and menu mix', null, 1),
  ('da1f2170-fe4f-45c5-9455-8270e22f7754', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'e6fe2cf1-dbec-4d3f-aabc-1b18f51cc337', 'concept'::public.curated_course_node_type, 'Seasonality, events, competitors, macro conditions, weather, confidence ranges, and forecast bias', null, 2),
  ('fb2da0c1-1461-47bb-becf-fcd96cc054a1', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'b3ee96da-e745-4bdf-b9b8-8625803f23fc', 'subtopic'::public.curated_course_node_type, 'Expense, staffing, cash, and balance-sheet schedules', 'Students build a linked plan so demand drives resources and the operating result connects to liquidity and investment needs.', 2),
  ('6e34d924-7d6f-4298-b945-e7f50636bffb', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'fb2da0c1-1461-47bb-becf-fcd96cc054a1', 'concept'::public.curated_course_node_type, 'Food and beverage purchases, labor hours, payroll taxes/benefits, supplies, utilities, fees, repairs, and marketing', null, 0),
  ('c33cb5b2-60cc-43f7-b55e-0a1d64b7f013', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'fb2da0c1-1461-47bb-becf-fcd96cc054a1', 'concept'::public.curated_course_node_type, 'Receivables, inventory, payables, deposits, gift cards, loyalty liabilities, accruals, and cash timing', null, 1),
  ('dd39e7a9-4225-4ec8-b0aa-617500bfade0', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'fb2da0c1-1461-47bb-becf-fcd96cc054a1', 'concept'::public.curated_course_node_type, 'Capital expenditures, depreciation, debt service, owner funding, minimum cash, and covenant awareness', null, 2),
  ('a2c52d94-7bb1-42e7-8ca3-0fd77e066f12', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', null, 'topic'::public.curated_course_node_type, 'Flexible Budgets, Standards, and Variance Analysis', 'A variance is the start of an investigation, not a verdict. Students learn to separate volume, price, mix, efficiency, and capacity effects and to connect financial differences to operational causes and corrective action.', 5),
  ('60115ca0-5898-4b31-8861-dc17f3e6f7d6', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a2c52d94-7bb1-42e7-8ca3-0fd77e066f12', 'subtopic'::public.curated_course_node_type, 'Static and flexible budget comparison', 'Students restate expected cost at actual activity so managers are not rewarded or blamed simply for demand differences.', 0),
  ('175ad0ef-51db-4c32-ba16-1100cdaf8f49', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '60115ca0-5898-4b31-8861-dc17f3e6f7d6', 'concept'::public.curated_course_node_type, 'Planning budget, flexible budget, actual result, activity variance, and spending variance', null, 0),
  ('6f7b2892-1597-4dcb-9c78-1f1e085efb84', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '60115ca0-5898-4b31-8861-dc17f3e6f7d6', 'concept'::public.curated_course_node_type, 'Relevant activity drivers for rooms, F&B, banquets, housekeeping, maintenance, and utilities', null, 1),
  ('844b06ab-d6f4-4761-b93c-3c46fe696692', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '60115ca0-5898-4b31-8861-dc17f3e6f7d6', 'concept'::public.curated_course_node_type, 'Fixed, variable, mixed, step, and discretionary responses within the relevant range', null, 2),
  ('2f5340de-ae93-44ec-ba31-70e1898f8ba9', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a2c52d94-7bb1-42e7-8ca3-0fd77e066f12', 'subtopic'::public.curated_course_node_type, 'Standard costs and operational variances', 'This subtopic decomposes ingredient, beverage, labor, and other inputs into price and usage or efficiency components.', 1),
  ('cbdcccc8-d88d-4a92-9d0e-c10076c0a728', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '2f5340de-ae93-44ec-ba31-70e1898f8ba9', 'concept'::public.curated_course_node_type, 'Standard quantity, standard price/rate, actual quantity, actual price/rate, and variance formulas', null, 0),
