  ('80cb7910-bf45-49e1-808b-48e6ab1620d1', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a2c52d94-7bb1-42e7-8ca3-0fd77e066f12', 'subtopic'::public.curated_course_node_type, 'Root cause, control, and learning', 'Students interpret materiality, responsibility, timing, and controllability before recommending action.', 2),
  ('ad9b713d-13f6-4a07-b967-7853b7c6f278', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '80cb7910-bf45-49e1-808b-48e6ab1620d1', 'concept'::public.curated_course_node_type, 'Thresholds, exceptions, trend, recurrence, favorable/unfavorable labels, and absolute versus percentage effects', null, 0),
  ('fbdd564a-d124-4bc3-a80d-84288a66102e', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '80cb7910-bf45-49e1-808b-48e6ab1620d1', 'concept'::public.curated_course_node_type, 'Operational drivers, data errors, timing, external shocks, cross-department dependencies, and unintended incentives', null, 1),
  ('2ca252f4-346d-4f8a-8ba5-b4d6ca007de7', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '80cb7910-bf45-49e1-808b-48e6ab1620d1', 'concept'::public.curated_course_node_type, 'Owner, corrective action, forecast update, control change, benefit tracking, and post-action review', null, 2),
  ('1f198d51-ac40-4ed3-a462-443c8b381a35', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', null, 'topic'::public.curated_course_node_type, 'Food and Beverage Cost Control and Menu Profitability', 'Food and beverage accounting joins purchasing, recipes, production, service, waste, pricing, and guest choice. Students learn to protect margin without sacrificing safety, quality, employee capability, or the concept''s value proposition.', 6),
  ('b196389b-abda-4cba-838e-dbccb02cad9b', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '1f198d51-ac40-4ed3-a462-443c8b381a35', 'subtopic'::public.curated_course_node_type, 'Sales, recipes, and theoretical cost', 'Students connect POS sales and recipe specifications to the expected consumption and contribution of each item.', 0);
