  ('4d387b34-a54f-47fd-8114-6238e3e7d85b', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '7d7f7b80-fa89-4a28-9044-f7141f5bfe55', 'concept'::public.curated_course_node_type, 'Rooms cleaned per hour, covers per labor hour, labor hours per occupied room, revenue per labor hour, and labor cost percentage', null, 0),
