  ('5586a36e-96d2-4e04-a999-0749f96e1cff', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '63476706-c8f8-4a2e-a89b-a236cf7e0b6e', 'concept'::public.curated_course_node_type, 'GOPPAR, TRevPAR, EBITDA-related measures, cash available, debt-service awareness, and covenant context', null, 1),
  ('43d54d48-28bd-4bea-b6c2-e8b1fc0cfa2b', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '63476706-c8f8-4a2e-a89b-a236cf7e0b6e', 'concept'::public.curated_course_node_type, 'Management-contract definitions, performance tests, owner/operator adjustments, comparability, and reconciliation', null, 2),
  ('a5be5902-d2a1-4ae8-ba53-cea9bf25bcc1', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', null, 'topic'::public.curated_course_node_type, 'Relevant Costs and Short-Run Operating Decisions', 'Many managerial choices concern the future cash flows that differ among alternatives. Students learn to exclude sunk and unavoidable amounts, identify opportunity cost and constraints, and present both quantitative and qualitative consequences.', 9),
  ('db1b01f5-bb03-4ca9-8c9d-3c9b18ad69d9', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a5be5902-d2a1-4ae8-ba53-cea9bf25bcc1', 'subtopic'::public.curated_course_node_type, 'Relevant-cost framework', 'Students structure a decision around alternatives, time horizon, incremental cash flows, capacity, risks, and strategic effects.', 0),
  ('22fe6b40-5b81-4be2-8e1f-c168fe109db0', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'db1b01f5-bb03-4ca9-8c9d-3c9b18ad69d9', 'concept'::public.curated_course_node_type, 'Relevant, irrelevant, sunk, avoidable, incremental, differential, committed, and opportunity costs', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('0d95f931-be44-4eae-90d6-48161a6be361', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'db1b01f5-bb03-4ca9-8c9d-3c9b18ad69d9', 'concept'::public.curated_course_node_type, 'Traceable fixed costs, allocated common costs, cash versus noncash items, taxes, and working capital', null, 1),
  ('112e771d-76c4-4ba9-93ee-c7c932f5fa46', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'db1b01f5-bb03-4ca9-8c9d-3c9b18ad69d9', 'concept'::public.curated_course_node_type, 'Quantitative model, qualitative factors, stakeholders, reversibility, uncertainty, and decision rights', null, 2),
  ('9dafc62e-d708-44e1-9877-ba4446e9999f', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a5be5902-d2a1-4ae8-ba53-cea9bf25bcc1', 'subtopic'::public.curated_course_node_type, 'Recurring hospitality decisions', 'This subtopic applies the framework to choices managers routinely face across lodging, foodservice, and events.', 1),
  ('07cb7e6d-e3de-4941-a93c-c383c18a743a', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '9dafc62e-d708-44e1-9877-ba4446e9999f', 'concept'::public.curated_course_node_type, 'Special orders, groups, packages, discounts, upgrades, promotions, minimum guarantees, and displacement', null, 0),
  ('916a7cac-2700-42b4-88e7-72b62f8fe790', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '9dafc62e-d708-44e1-9877-ba4446e9999f', 'concept'::public.curated_course_node_type, 'Make or buy, outsource, insource, lease or service, centralize or decentralize, repair or replace, and technology vendors', null, 1),
  ('f09d4c1e-d862-48f6-aa1d-2ef6961e5710', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '9dafc62e-d708-44e1-9877-ba4446e9999f', 'concept'::public.curated_course_node_type, 'Keep or drop an outlet, menu item, service, amenity, shift, channel, customer, event, or property segment', null, 2),
  ('1eeae016-14f5-415d-ad92-23df9b30bedb', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a5be5902-d2a1-4ae8-ba53-cea9bf25bcc1', 'subtopic'::public.curated_course_node_type, 'Constraints and optimization', 'Students prioritize scarce rooms, seats, labor, kitchen time, event space, equipment, or capital based on contribution and strategic fit.', 2),
  ('d36c4a8d-7660-4d62-ac27-a4f006f49358', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '1eeae016-14f5-415d-ad92-23df9b30bedb', 'concept'::public.curated_course_node_type, 'Contribution per constrained resource, bottlenecks, throughput, shadow cost, and unused capacity', null, 0),
  ('1b58ad0e-16a4-41d3-85ab-da434a7a0c5d', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '1eeae016-14f5-415d-ad92-23df9b30bedb', 'concept'::public.curated_course_node_type, 'Product or customer mix, minimum commitments, quality constraints, sequencing, and demand uncertainty', null, 1),
  ('81c8ed9b-e812-48c9-b365-c2031bb65e12', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '1eeae016-14f5-415d-ad92-23df9b30bedb', 'concept'::public.curated_course_node_type, 'Integer decisions, solver models, sensitivity, implementation feasibility, and ethical guardrails', null, 2),
  ('0ba1894e-1f3a-4695-a93d-f1ac7f79ac05', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', null, 'topic'::public.curated_course_node_type, 'Pricing, Revenue Management, and Customer/Channel Profitability', 'Price is both a financial lever and a promise to the guest. This section combines cost information with demand, competition, capacity, channel economics, and lifetime value without treating cost-plus pricing as the only answer.', 10),
  ('07af3347-f008-455b-84f6-17cc21ae2ad5', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '0ba1894e-1f3a-4695-a93d-f1ac7f79ac05', 'subtopic'::public.curated_course_node_type, 'Pricing foundations', 'Students compare cost, market, value, demand, and strategic approaches and identify what each can and cannot reveal.', 0),
  ('79b96ee8-e7ac-48ac-9e9e-086199b506fd', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '07af3347-f008-455b-84f6-17cc21ae2ad5', 'concept'::public.curated_course_node_type, 'Cost-plus, target return, value-based, competitive, dynamic, package, subscription, membership, and promotional pricing', null, 0),
  ('e354dd25-e352-4aeb-b338-b5b6fedd4dde', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '07af3347-f008-455b-84f6-17cc21ae2ad5', 'concept'::public.curated_course_node_type, 'Floor price, full cost, incremental cost, willingness to pay, elasticity, reference price, and fairness', null, 1),
  ('d004052c-1b70-493f-ae0b-e42a87ef1b42', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '07af3347-f008-455b-84f6-17cc21ae2ad5', 'concept'::public.curated_course_node_type, 'Rate fences, versioning, bundles, discounts, service charges, resort fees, taxes, and transparent disclosure', null, 2),
  ('a9052e8e-5238-4523-9e39-0f795d86b35a', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '0ba1894e-1f3a-4695-a93d-f1ac7f79ac05', 'subtopic'::public.curated_course_node_type, 'Revenue-management economics', 'This subtopic connects perishable capacity to forecasting, inventory controls, displacement, and total contribution.', 1),
  ('4a9d2cc8-cde9-4225-9c90-b24fc48f87fd', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a9052e8e-5238-4523-9e39-0f795d86b35a', 'concept'::public.curated_course_node_type, 'Demand forecast, unconstrained demand, price, availability, length-of-stay controls, overbooking, and cancellations', null, 0),
  ('e8f32557-ee2c-4c07-8f44-b8c7c1e65423', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a9052e8e-5238-4523-9e39-0f795d86b35a', 'concept'::public.curated_course_node_type, 'Group displacement, function-space opportunity, transient versus group, ancillary spend, and total revenue', null, 1),
  ('e443eb37-91ff-4d99-ba6b-e2682a62aebe', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'a9052e8e-5238-4523-9e39-0f795d86b35a', 'concept'::public.curated_course_node_type, 'ADR, occupancy, RevPAR, contribution RevPAR, TRevPAR, forecast error, and override governance', null, 2),
  ('28c5f0f1-c770-4c7c-89f7-6a435d46e31c', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '0ba1894e-1f3a-4695-a93d-f1ac7f79ac05', 'subtopic'::public.curated_course_node_type, 'Customer, segment, product, and channel profitability', 'Students look beyond revenue to the resources, discounts, commissions, service requirements, and retention economics associated with different demand.', 2),
  ('46762957-9a7b-415d-89cb-d4043ef6f031', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '28c5f0f1-c770-4c7c-89f7-6a435d46e31c', 'concept'::public.curated_course_node_type, 'Direct product and service costs, order and support activities, acquisition, loyalty, returns, complaints, and bad debt', null, 0),
  ('a473c264-8124-4e3d-bd4b-e5351ee0160f', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '28c5f0f1-c770-4c7c-89f7-6a435d46e31c', 'concept'::public.curated_course_node_type, 'Customer, group, corporate account, membership, event, menu item, channel, and cohort contribution', null, 1),
  ('3b4c2652-0979-4a60-8053-ba8c6c6e63e8', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '28c5f0f1-c770-4c7c-89f7-6a435d46e31c', 'concept'::public.curated_course_node_type, 'Lifetime value, retention, incremental behavior, cannibalization, attribution, data limits, privacy, and fairness', null, 2),
  ('fbf45f9b-d697-4765-a996-c444d44b55f2', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', null, 'topic'::public.curated_course_node_type, 'Responsibility Accounting, Performance Measurement, and Dashboards', 'Performance systems shape attention and behavior. Students learn to assign accountability only where managers have influence, combine financial and nonfinancial measures, and build dashboards that lead to action rather than data theater.', 11),
  ('fbf66cc1-96e4-46cf-9883-7851dd5101b5', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'fbf45f9b-d697-4765-a996-c444d44b55f2', 'subtopic'::public.curated_course_node_type, 'Responsibility centers and controllability', 'Students align decision authority, resources, measures, and evaluation across the organization.', 0),
  ('cfdafce7-f53e-45a4-a727-2a5892bc1416', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'fbf66cc1-96e4-46cf-9883-7851dd5101b5', 'concept'::public.curated_course_node_type, 'Revenue, cost, profit, and investment centers; property, department, outlet, cluster, and corporate roles', null, 0),
  ('583e5dd8-1c9a-4d8a-a6fe-b3f19e1891a1', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'fbf66cc1-96e4-46cf-9883-7851dd5101b5', 'concept'::public.curated_course_node_type, 'Controllable versus noncontrollable items, direct versus allocated cost, shared services, and influence', null, 1),
  ('e588a0f5-fd8d-4254-86ea-cc76b736a430', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'fbf66cc1-96e4-46cf-9883-7851dd5101b5', 'concept'::public.curated_course_node_type, 'Transfer prices, service-level agreements, internal charges, goal congruence, and disputes', null, 2),
  ('f9e0f2d0-7818-4f21-8b70-398d2288cbfa', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'fbf45f9b-d697-4765-a996-c444d44b55f2', 'subtopic'::public.curated_course_node_type, 'Financial and operating performance measures', 'This subtopic selects a balanced set of leading and lagging indicators connected to strategy and controllable drivers.', 1),
  ('bf4cbda5-fc8c-421c-9c0d-f1da8b58627d', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'f9e0f2d0-7818-4f21-8b70-398d2288cbfa', 'concept'::public.curated_course_node_type, 'Margin, flow-through, ROI, residual income, economic profit, asset turnover, and cash measures', null, 0),
  ('fd93c7c2-6fcb-43d6-9e04-e65df21079e8', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'f9e0f2d0-7818-4f21-8b70-398d2288cbfa', 'concept'::public.curated_course_node_type, 'Guest satisfaction, quality, complaints, loyalty, employee retention, safety, productivity, accessibility, and sustainability', null, 1),
  ('947d7a52-1740-4d68-b0f7-472d8d65573a', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'f9e0f2d0-7818-4f21-8b70-398d2288cbfa', 'concept'::public.curated_course_node_type, 'Targets, benchmarks, trends, seasonality, thresholds, confidence, materiality, and unintended incentives', null, 2),
  ('8c073d52-9ded-4c6f-8afd-e0191a709c55', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'fbf45f9b-d697-4765-a996-c444d44b55f2', 'subtopic'::public.curated_course_node_type, 'Dashboard and review design', 'Students turn metrics into a governance routine with definitions, owners, investigation, action, and follow-through.', 2),
  ('037ce29a-d739-4bd8-96f1-5090558cc510', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '8c073d52-9ded-4c6f-8afd-e0191a709c55', 'concept'::public.curated_course_node_type, 'Audience, decision, metric dictionary, grain, source, refresh, target, visualization, and accessibility', null, 0),
  ('586f1942-4fe5-4a0a-a66e-2ea1f982466b', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '8c073d52-9ded-4c6f-8afd-e0191a709c55', 'concept'::public.curated_course_node_type, 'Exception reporting, drill-down, annotations, commentary, forecast, actions, owners, due dates, and benefits', null, 1),
  ('a0988b98-52c9-4041-8f2d-ca71aa8aa79e', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '8c073d52-9ded-4c6f-8afd-e0191a709c55', 'concept'::public.curated_course_node_type, 'Daily flash, weekly operations, monthly close, quarterly owner review, and post-investment review', null, 2),
  ('06d4ed00-0b69-41ff-b958-0e4539877e87', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', null, 'topic'::public.curated_course_node_type, 'Capital Budgeting, Cash Flow, Risk, and Investment Decisions', 'Hospitality capital decisions affect guest experience, safety, brand compliance, efficiency, resilience, and asset value for years. Students learn to model incremental after-tax cash flows, compare methods, and make uncertainty visible.', 12),
  ('d6152aac-150f-48c5-bc47-ea4863160e24', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '06d4ed00-0b69-41ff-b958-0e4539877e87', 'subtopic'::public.curated_course_node_type, 'Project cash-flow construction', 'Students separate project economics from accounting profit and include all incremental consequences of the decision.', 0),
  ('0a4ee610-8bd7-4ced-b4e0-d8e320e5f86c', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'd6152aac-150f-48c5-bc47-ea4863160e24', 'concept'::public.curated_course_node_type, 'Initial outlay, installation, training, downtime, working capital, maintenance, operating savings, revenue effects, and terminal value', null, 0),
  ('dfb99adc-7b66-4503-95e5-5ca625780056', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'd6152aac-150f-48c5-bc47-ea4863160e24', 'concept'::public.curated_course_node_type, 'Depreciation tax shield, after-tax cash flow, cannibalization, opportunity cost, allocated overhead, and financing separation', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('5a3b025a-d2e6-46bb-9f71-aa4dfdac44b8', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'd6152aac-150f-48c5-bc47-ea4863160e24', 'concept'::public.curated_course_node_type, 'Renovations, equipment, guestrooms, kitchens, technology, energy projects, accessibility, safety, and mandated capital', null, 2),
  ('85f316bf-7290-4254-9ef8-38c92a870798', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '06d4ed00-0b69-41ff-b958-0e4539877e87', 'subtopic'::public.curated_course_node_type, 'Investment evaluation methods', 'This subtopic compares decision measures and explains when they may rank projects differently.', 1),
  ('f181e452-90ec-4ee7-9dd6-e267083d922e', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '85f316bf-7290-4254-9ef8-38c92a870798', 'concept'::public.curated_course_node_type, 'Net present value, internal rate of return, modified IRR, profitability index, payback, discounted payback, and accounting return', null, 0),
  ('f8656bb7-9997-4eaf-803d-8aa15456a077', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '85f316bf-7290-4254-9ef8-38c92a870798', 'concept'::public.curated_course_node_type, 'Discount rate, required return, project life, replacement chains, mutually exclusive projects, and capital rationing', null, 1),
  ('d0a45faf-37ce-4fc1-a935-19c256077022', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '85f316bf-7290-4254-9ef8-38c92a870798', 'concept'::public.curated_course_node_type, 'Spreadsheet functions, timeline consistency, sign conventions, rounding, audit checks, and interpretation', null, 2),
  ('3cc8e0d9-94ec-4ca5-b3e2-3bbe88bbfdb4', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '06d4ed00-0b69-41ff-b958-0e4539877e87', 'subtopic'::public.curated_course_node_type, 'Risk, scenario, and post-audit', 'Students evaluate uncertainty explicitly and establish how management will learn whether promised benefits occurred.', 2),
  ('165d2c7c-6782-4375-981f-b7e0c9483056', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '3cc8e0d9-94ec-4ca5-b3e2-3bbe88bbfdb4', 'concept'::public.curated_course_node_type, 'Sensitivity, scenario, break-even, decision tree, simulation concepts, real options, and risk-adjusted discount rates', null, 0),
  ('f2dcf0cb-e738-47ce-9d03-7bcd159e4749', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '3cc8e0d9-94ec-4ca5-b3e2-3bbe88bbfdb4', 'concept'::public.curated_course_node_type, 'Demand, rate, cost, schedule, technology, construction, regulatory, climate, and execution risks', null, 1),
  ('e60ff11f-b1a1-4ff7-a15e-8cf5175776ff', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '3cc8e0d9-94ec-4ca5-b3e2-3bbe88bbfdb4', 'concept'::public.curated_course_node_type, 'Stage gates, contingencies, approval, benefits owner, baseline, post-completion review, lessons, and corrective action', null, 2),
  ('1036b366-b1fd-4a5f-87e2-7b4dd4e0898a', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', null, 'topic'::public.curated_course_node_type, 'Internal Controls, Accounting Systems, Analytics, AI, and Sustainability', 'Reliable decisions require trustworthy processes, data, models, and controls. The final section integrates transaction cycles, analytics, automation, responsible AI, and sustainability accounting into a modern management-control system.', 13),
  ('f6aab6aa-3a35-40e7-84bf-99f4c167322d', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', '1036b366-b1fd-4a5f-87e2-7b4dd4e0898a', 'subtopic'::public.curated_course_node_type, 'Internal control and transaction cycles', 'Students apply preventive and detective controls to the high-volume, decentralized, cash- and data-intensive hospitality environment.', 0),
  ('36247fdb-5bee-44c1-b13d-3c903c014512', 'f1a2b3c4-5d6e-4f16-9a85-9b0c1d2e3f06', 'f6aab6aa-3a35-40e7-84bf-99f4c167322d', 'concept'::public.curated_course_node_type, 'COSO objectives and components; authorization, segregation, documentation, custody, reconciliation, review, and monitoring', null, 0),
