  'hospitality-managerial-accounting',
  null,
  'Hospitality Managerial Accounting',
  'Hospitality Managerial Accounting',
  'This course equips hospitality managers to plan, control, evaluate, and improve hotel, restaurant, resort, club, event, and multi-unit performance using financial and nonfinancial information. Students build contribution and CVP models, operating budgets and forecasts, flexible budgets and variance analyses, food/beverage and labor controls, departmental statements, relevant-cost decision models, pricing and profitability analyses, performance dashboards, and capital-investment cases. U.S. practice is emphasized through USALI 12th Revised Edition, restaurant account structures, IMA ethics, COSO-informed controls, and auditable spreadsheet discipline.',
  $hmacjson${"slug": "hospitality-managerial-accounting", "title": "Hospitality Managerial Accounting", "description": "This course equips hospitality managers to plan, control, evaluate, and improve hotel, restaurant, resort, club, event, and multi-unit performance using financial and nonfinancial information. Students build contribution and CVP models, operating budgets and forecasts, flexible budgets and variance analyses, food/beverage and labor controls, departmental statements, relevant-cost decision models, pricing and profitability analyses, performance dashboards, and capital-investment cases. U.S. practice is emphasized through USALI 12th Revised Edition, restaurant account structures, IMA ethics, COSO-informed controls, and auditable spreadsheet discipline.", "topics": [{"id": "cc2bad65-7938-4612-9624-26fa5ae2ceaf", "type": "topic", "title": "Managerial Accounting, Hospitality Value Creation, and Ethics", "description": "Managerial accounting turns financial and nonfinancial evidence into better planning, control, evaluation, and resource-allocation decisions. This opening section establishes the manager's role as an accountable user and steward of information—not merely a calculator of costs.", "children": [{"id": "8db506e1-f8a8-4558-9188-ae17488a5921", "type": "subtopic", "title": "Managerial versus financial accounting", "children": [{"id": "ba003f43-824b-4266-87de-ba95caab522f", "type": "concept", "title": "Internal users, operational focus, future orientation, timeliness, detail, and decision relevance"}, {"id": "698141d9-4b18-47e1-bc75-441022674ad4", "type": "concept", "title": "Relationship to U.S. GAAP-based records, audited statements, tax reporting, and owner or lender requirements"}, {"id": "b9ce0bed-7460-4595-8376-321fa2b421d5", "type": "concept", "title": "Planning, controlling, evaluating, learning, and communicating across hospitality departments"}], "description": "Students learn why internal reports differ from external statements and how decision purpose determines the relevant detail, timing, and format."}, {"id": "26183691-8c54-4ad8-a353-ccfa27e433f9", "type": "subtopic", "title": "Hospitality business models and value drivers", "children": [{"id": "0e08f0fa-00bc-4139-b050-efdc1028226f", "type": "concept", "title": "Hotels, resorts, restaurants, clubs, casinos, events, franchises, management companies, and mixed-use assets"}, {"id": "fa30bc7c-c320-4af9-bc54-3ec51dfec7d6", "type": "concept", "title": "Ownership, operator, brand, asset manager, landlord, lender, and third-party platform perspectives"}, {"id": "5ebec0b0-cda7-4358-8061-ac83b4d26d5c", "type": "concept", "title": "Capacity, occupancy, covers, average checks, rate, mix, labor, quality, loyalty, channel cost, and asset intensity"}], "description": "This subtopic links accounting information to the distinctive economics of perishable capacity, high fixed costs, variable demand, and multiple revenue centers."}, {"id": "a412f407-a6a3-4264-903a-31c34855e49d", "type": "subtopic", "title": "Ethics and professional judgment", "children": [{"id": "896cc339-4fb9-4845-baad-840d55777154", "type": "concept", "title": "IMA principles: honesty, fairness, objectivity, and responsibility"}, {"id": "e7cf32e8-986d-48d7-9324-7e9232034135", "type": "concept", "title": "IMA standards: competence, confidentiality, integrity, and credibility"}, {"id": "7a537ebe-b4e7-4cc9-a7ee-33dbac89a9c4", "type": "concept", "title": "Budget gaming, earnings manipulation, biased assumptions, omitted risks, data privacy, speaking up, escalation, and documentation"}], "description": "Students apply ethical standards when estimates, targets, incentives, and pressure could distort information or behavior."}]}, {"id": "e1579842-456f-4e89-b426-38c3d6a69726", "type": "topic", "title": "Hospitality Account Structures and Departmental Statements", "description": "Hospitality managers need a shared reporting language to compare departments, properties, periods, budgets, and peers. This section introduces industry account structures while emphasizing that internal reports must remain faithful to underlying transactions and management contracts.", "children": [{"id": "0a130a7e-b700-4f59-9605-40bf99d51aa1", "type": "subtopic", "title": "Uniform systems and chart-of-accounts design", "children": [{"id": "b54dde0a-e54b-44b1-9827-9e115af94629", "type": "concept", "title": "Uniform System of Accounts for the Lodging Industry (USALI), 12th Revised Edition, effective January 1, 2026"}, {"id": "f0823cc0-de9b-402e-883b-dfa77500123f", "type": "concept", "title": "Uniform System of Accounts for Restaurants and operation-specific account maps"}, {"id": "5451a1e0-4109-4ca4-86db-88dcec93919c", "type": "concept", "title": "Account codes, dimensions, departments, revenue centers, cost centers, entities, projects, channels, and responsibility owners"}], "description": "Students learn how standardized account structures improve consistency without eliminating property-specific managerial detail."}, {"id": "f1227d73-0a60-4661-bb3e-8bd4b4399da7", "type": "subtopic", "title": "Lodging operating statements", "children": [{"id": "e92f02e6-b7f5-4383-a7ed-515def704acc", "type": "concept", "title": "Rooms, food and beverage, other operated departments, miscellaneous income, and departmental profit"}, {"id": "325b1f67-6d3a-4ec2-999a-222ec4ea6c69", "type": "concept", "title": "Administrative and general, information and telecommunications systems, sales and marketing, property operations and maintenance, and utilities"}, {"id": "8f30f6fd-31fa-4601-ba5e-8da6bd2266b3", "type": "concept", "title": "Gross operating profit, management fees, non-operating income and expenses, fixed charges, owner items, and reconciliation"}], "description": "This subtopic explains how revenues and expenses flow through operated and undistributed departments to property-level results."}, {"id": "cb98aca4-811e-4ba6-820c-3276c762678c", "type": "subtopic", "title": "Restaurant and multi-outlet statements", "children": [{"id": "86878b6a-13e8-4842-a767-853efc7496a6", "type": "concept", "title": "Food, beverage, merchandise, catering, delivery, service charges, discounts, comps, and taxes"}, {"id": "629915e6-0c78-470d-9b01-a3e7b83e392e", "type": "concept", "title": "Cost of sales, payroll and related costs, controllable operating expenses, occupancy, and corporate allocations"}, {"id": "ea0fcd95-1be8-4272-9530-d5bcfa79e7aa", "type": "concept", "title": "Single-unit, outlet, daypart, concept, event, location, and consolidated reporting"}], "description": "Students organize sales and costs so chefs, outlet leaders, and general managers can see volume, mix, margin, and accountability."}]}, {"id": "e3d6fe9b-6d67-44f3-84a5-4e95a11cf074", "type": "topic", "title": "Cost Concepts, Assignment, Behavior, and Estimation", "description": "A cost has meaning only in relation to a question. Students learn to classify, trace, allocate, and estimate costs so models reflect operational reality rather than convenient labels.", "children": [{"id": "718690c4-b346-4049-a612-6056cafe0b6b", "type": "subtopic", "title": "Cost objects and classifications", "children": [{"id": "a7f52224-0054-4627-b06c-4dfa3e88514c", "type": "concept", "title": "Direct and indirect; product/service and period; controllable and noncontrollable"}, {"id": "07608028-f900-4e8c-bf9f-0d3e669a5dd6", "type": "concept", "title": "Fixed, variable, mixed, step, committed, discretionary, avoidable, sunk, incremental, and opportunity costs"}, {"id": "e716d1a5-768e-4b38-8d95-03076e808c7a", "type": "concept", "title": "Relevant range, time horizon, capacity level, unit cost, total cost, and allocation purpose"}], "description": "Students identify the guest, room, menu item, outlet, event, channel, department, property, or decision whose economics are being measured."}, {"id": "ffe76cab-c439-4479-80c8-2e312d343c0f", "type": "subtopic", "title": "Cost assignment and allocation", "children": [{"id": "934ca5ad-c279-4392-87f0-e50659f9ca8c", "type": "concept", "title": "Tracing, allocation, cost pools, cost drivers, reciprocal services, and allocation bases"}, {"id": "e7622149-acc2-4f62-b28d-36def8793176", "type": "concept", "title": "Traditional departmental allocation, activity-based costing, time-driven activity-based costing, and capacity cost rates"}, {"id": "89228625-5f21-4eb5-9fbb-1fbc1ea64d68", "type": "concept", "title": "Causality, benefits received, ability to bear, simplicity, consistency, incentives, and allocation disputes"}], "description": "This subtopic develops fair, useful methods for assigning shared resources without confusing allocated cost with avoidable cost."}, {"id": "dc292872-d93e-46fc-8f09-8ffc4d8bd6de", "type": "subtopic", "title": "Cost behavior and estimation", "children": [{"id": "429f195c-9100-4507-9af3-83f605548de1", "type": "concept", "title": "Account analysis, engineering estimates, scatterplots, high-low method, and regression"}, {"id": "fae837e3-433d-4029-a9ce-66f048cd6bce", "type": "concept", "title": "Outliers, seasonality, inflation, structural breaks, nonlinear effects, learning, and capacity steps"}, {"id": "edc6001c-c14c-4040-a470-87a101275f19", "type": "concept", "title": "Model fit, residuals, reasonableness, sensitivity, confidence, validation, and update cadence"}], "description": "Students use data and operational knowledge to estimate how costs respond to volume, mix, time, and constraints."}]}, {"id": "0079e25f-26a3-43b5-817e-2a08167baa85", "type": "topic", "title": "Contribution Margin, Cost-Volume-Profit, and Profit Planning", "description": "Contribution analysis shows how price, volume, mix, variable cost, and fixed cost combine to produce profit. Students use it to test operating plans while recognizing that simplified models require clear assumptions.", "children": [{"id": "a0e68f0f-0f1d-46bb-8f70-4882054b3c9f", "type": "subtopic", "title": "Contribution format and unit economics", "children": [{"id": "3bdfae29-f89e-4408-9acc-8549630eb196", "type": "concept", "title": "Revenue, variable cost, contribution margin, contribution margin ratio, and traceable fixed cost"}, {"id": "aab59c5c-2211-42ba-afb1-0a785811b281", "type": "concept", "title": "Per occupied room, available room, cover, seat-hour, order, event, member, and channel unit economics"}, {"id": "92763ff0-e754-4ea8-8d90-5d733bdd352f", "type": "concept", "title": "Gross margin versus contribution margin; service charges, commissions, merchant fees, and incremental labor"}], "description": "Students reorganize results by cost behavior to reveal the incremental economics of rooms, covers, events, and channels."}, {"id": "14a90dae-ceaf-4c8e-812f-c039981af421", "type": "subtopic", "title": "Break-even and target-profit analysis", "children": [{"id": "6b723201-0f6b-4774-a2c3-dc166cd17550", "type": "concept", "title": "Break-even units and sales dollars; target-profit volume; margin of safety; degree of operating leverage"}, {"id": "2c32f9bc-03dc-41d7-a107-13185928bde4", "type": "concept", "title": "Single-product, multiproduct, weighted sales mix, composite units, and changing mix"}, {"id": "1aa954c1-e58d-4e63-ad24-c8b850168327", "type": "concept", "title": "Taxes where relevant, capacity limits, seasonality, step costs, ramp-up, and shutdown points"}], "description": "This subtopic translates a profit objective into the sales, occupancy, covers, check average, or room-rate conditions needed to reach it."}, {"id": "afecfdbd-eb0e-477f-8590-d401f0d4626e", "type": "subtopic", "title": "What-if and sensitivity analysis", "children": [{"id": "03743b69-c09d-4047-a11d-ec17fa56586d", "type": "concept", "title": "Price-volume-cost tradeoffs, promotions, discounting, wage or food inflation, and channel shifts"}, {"id": "01e868e6-a1c5-4eb3-8ff9-83a7950d59cc", "type": "concept", "title": "One-way and two-way data tables, scenarios, tornado charts, goal seek, and break-even surfaces"}, {"id": "905e956c-255e-4b0d-a284-3ed730a702f3", "type": "concept", "title": "Base, upside, downside, stress, trigger, contingency, and decision thresholds"}], "description": "Students move beyond one-point answers to identify the assumptions that matter and the combinations that threaten or improve the plan."}]}, {"id": "b3ee96da-e745-4bdf-b9b8-8625803f23fc", "type": "topic", "title": "Budgeting, Forecasting, and Integrated Operating Plans", "description": "Budgets coordinate strategy, demand, staffing, purchasing, capital, and cash. This section emphasizes driver-based plans that managers can update and act on—not annual numbers created only to satisfy headquarters.", "children": [{"id": "f668608c-85bf-429f-900a-977f630881b4", "type": "subtopic", "title": "Budget architecture and governance", "children": [{"id": "3bd93733-e30e-48b2-afbf-1c5f370e05a8", "type": "concept", "title": "Strategic plan, annual operating budget, rolling forecast, long-range plan, and capital plan"}, {"id": "f4226fbd-ba88-4162-add5-66f3122931aa", "type": "concept", "title": "Budget calendar, owners, assumptions book, templates, review meetings, challenge process, and sign-off"}, {"id": "305dce6d-52c3-4cb2-a82e-188e3694c58b", "type": "concept", "title": "Top-down targets, bottom-up plans, participative budgeting, negotiated goals, slack, and ethics"}], "description": "Students learn how assumptions, schedules, responsibilities, approvals, and versions combine into a coherent plan."}, {"id": "e6fe2cf1-dbec-4d3f-aabc-1b18f51cc337", "type": "subtopic", "title": "Revenue and volume forecasting", "children": [{"id": "8c8605f7-4eda-49f5-9381-57f773f35fac", "type": "concept", "title": "Occupancy, ADR, room nights, pace, pickup, cancellations, no-shows, length of stay, and channel mix"}, {"id": "7bdd0172-d513-4707-92a6-8e588e8b286e", "type": "concept", "title": "Covers, check average, seat turns, dayparts, catering, events, delivery, and menu mix"}, {"id": "da1f2170-fe4f-45c5-9455-8270e22f7754", "type": "concept", "title": "Seasonality, events, competitors, macro conditions, weather, confidence ranges, and forecast bias"}], "description": "This subtopic connects market demand and operational capacity to rooms, covers, events, membership, and ancillary revenue."}, {"id": "fb2da0c1-1461-47bb-becf-fcd96cc054a1", "type": "subtopic", "title": "Expense, staffing, cash, and balance-sheet schedules", "children": [{"id": "6e34d924-7d6f-4298-b945-e7f50636bffb", "type": "concept", "title": "Food and beverage purchases, labor hours, payroll taxes/benefits, supplies, utilities, fees, repairs, and marketing"}, {"id": "c33cb5b2-60cc-43f7-b55e-0a1d64b7f013", "type": "concept", "title": "Receivables, inventory, payables, deposits, gift cards, loyalty liabilities, accruals, and cash timing"}, {"id": "dd39e7a9-4225-4ec8-b0aa-617500bfade0", "type": "concept", "title": "Capital expenditures, depreciation, debt service, owner funding, minimum cash, and covenant awareness"}], "description": "Students build a linked plan so demand drives resources and the operating result connects to liquidity and investment needs."}]}, {"id": "a2c52d94-7bb1-42e7-8ca3-0fd77e066f12", "type": "topic", "title": "Flexible Budgets, Standards, and Variance Analysis", "description": "A variance is the start of an investigation, not a verdict. Students learn to separate volume, price, mix, efficiency, and capacity effects and to connect financial differences to operational causes and corrective action.", "children": [{"id": "60115ca0-5898-4b31-8861-dc17f3e6f7d6", "type": "subtopic", "title": "Static and flexible budget comparison", "children": [{"id": "175ad0ef-51db-4c32-ba16-1100cdaf8f49", "type": "concept", "title": "Planning budget, flexible budget, actual result, activity variance, and spending variance"}, {"id": "6f7b2892-1597-4dcb-9c78-1f1e085efb84", "type": "concept", "title": "Relevant activity drivers for rooms, F&B, banquets, housekeeping, maintenance, and utilities"}, {"id": "844b06ab-d6f4-4761-b93c-3c46fe696692", "type": "concept", "title": "Fixed, variable, mixed, step, and discretionary responses within the relevant range"}], "description": "Students restate expected cost at actual activity so managers are not rewarded or blamed simply for demand differences."}, {"id": "2f5340de-ae93-44ec-ba31-70e1898f8ba9", "type": "subtopic", "title": "Standard costs and operational variances", "children": [{"id": "cbdcccc8-d88d-4a92-9d0e-c10076c0a728", "type": "concept", "title": "Standard quantity, standard price/rate, actual quantity, actual price/rate, and variance formulas"}, {"id": "e5bc6d97-3eef-43b2-93e3-30c28e714356", "type": "concept", "title": "Purchase price, material usage, yield, mix, labor rate, labor efficiency, overtime, and staffing mix"}, {"id": "ec9f6a81-a225-430f-86dc-1937ece53fb2", "type": "concept", "title": "Sales price, volume, mix, market-size/share, occupancy, ADR, covers, and average-check variances"}], "description": "This subtopic decomposes ingredient, beverage, labor, and other inputs into price and usage or efficiency components."}, {"id": "80cb7910-bf45-49e1-808b-48e6ab1620d1", "type": "subtopic", "title": "Root cause, control, and learning", "children": [{"id": "ad9b713d-13f6-4a07-b967-7853b7c6f278", "type": "concept", "title": "Thresholds, exceptions, trend, recurrence, favorable/unfavorable labels, and absolute versus percentage effects"}, {"id": "fbdd564a-d124-4bc3-a80d-84288a66102e", "type": "concept", "title": "Operational drivers, data errors, timing, external shocks, cross-department dependencies, and unintended incentives"}, {"id": "2ca252f4-346d-4f8a-8ba5-b4d6ca007de7", "type": "concept", "title": "Owner, corrective action, forecast update, control change, benefit tracking, and post-action review"}], "description": "Students interpret materiality, responsibility, timing, and controllability before recommending action."}]}, {"id": "1f198d51-ac40-4ed3-a462-443c8b381a35", "type": "topic", "title": "Food and Beverage Cost Control and Menu Profitability", "description": "Food and beverage accounting joins purchasing, recipes, production, service, waste, pricing, and guest choice. Students learn to protect margin without sacrificing safety, quality, employee capability, or the concept's value proposition.", "children": [{"id": "b196389b-abda-4cba-838e-dbccb02cad9b", "type": "subtopic", "title": "Sales, recipes, and theoretical cost", "children": [{"id": "68cd1808-c1bd-413f-94b2-1cb34b5af273", "type": "concept", "title": "Menu hierarchy, portion, yield, edible portion, standard recipe, substitutions, modifiers, comps, and voids"}, {"id": "d71e8488-da1b-4ccd-a9fe-559ea44aa050", "type": "concept", "title": "Theoretical cost, actual cost, cost percentage, gross profit, contribution, popularity, and menu engineering"}, {"id": "7a83d071-2de5-4782-abbb-d700a8382abb", "type": "concept", "title": "Food, beverage, banquet, catering, minibar, room service, delivery, and outlet differences"}], "description": "Students connect POS sales and recipe specifications to the expected consumption and contribution of each item."}, {"id": "2232b2b1-dc9e-4822-93cc-f063ce1d9ac7", "type": "subtopic", "title": "Purchasing, receiving, inventory, and reconciliation", "children": [{"id": "1e0da1a2-eef8-4a49-9025-7aa8bdd0a6b1", "type": "concept", "title": "Specifications, bids, purchase orders, receiving, invoices, credits, transfers, requisitions, and storage"}, {"id": "b4d745c0-d9e1-480c-b602-f0c454501c74", "type": "concept", "title": "Beginning inventory + purchases - ending inventory = consumption; perpetual versus periodic records"}, {"id": "375346b4-d895-4e35-bd5b-90ff5c7e8458", "type": "concept", "title": "Price, yield, waste, spoilage, theft, breakage, transfers, staff meals, count error, and cut-off"}], "description": "This subtopic follows product from approved supplier to count sheet, protecting availability, cash, safety, and traceability."}, {"id": "b47cac29-25c9-4002-9c97-2a0715e0a704", "type": "subtopic", "title": "Beverage, banquet, and event controls", "children": [{"id": "a3ff1d9b-2a7c-436a-af72-2f88138efbbf", "type": "concept", "title": "Bottle, ounce, keg, draft, wine, cocktail recipe, pour cost, open-bar, hosted, and cash-bar controls"}, {"id": "4db5745f-d01f-459f-878d-9fd8aa2f46b3", "type": "concept", "title": "Guarantees, consumption reports, package revenue, service charges, gratuities, commissions, and event settlements"}, {"id": "7fb2dc90-5a38-450c-b453-b138d75537b5", "type": "concept", "title": "Key custody, storeroom access, requisitions, comp authority, spot counts, variance investigation, and responsible service"}], "description": "Students examine control designs for high-value, high-variance, package, consumption, and hosted service environments."}]}, {"id": "17f53cb9-caba-4462-b684-5a396589ace5", "type": "topic", "title": "Labor Cost Planning, Productivity, and Workforce Decisions", "description": "Labor is both a major cost and the human system that creates service. This section teaches managers to align demand, staffing, skills, pay, productivity, quality, and employee well-being rather than minimizing labor in isolation.", "children": [{"id": "6c76ce97-c1de-4f13-9104-b85de62fbb9a", "type": "subtopic", "title": "Labor cost architecture", "children": [{"id": "05d615a0-eb59-440d-98f9-2aa0b3740032", "type": "concept", "title": "Wages, salaries, overtime, premiums, tips, service charges, payroll taxes, benefits, incentives, and paid leave"}, {"id": "8a9884d2-f730-47eb-ad08-b84c930b935f", "type": "concept", "title": "Productive, nonproductive, training, meeting, onboarding, absence, vacancy, and turnover time"}, {"id": "1f8c7ac0-a8b0-4b8d-9d66-2a126b34f90e", "type": "concept", "title": "Department, job, shift, daypart, outlet, property, agency, and corporate allocations"}], "description": "Students identify the full cost and timing of work across hourly, salaried, temporary, contracted, and shared-service arrangements."}, {"id": "7d7f7b80-fa89-4a28-9044-f7141f5bfe55", "type": "subtopic", "title": "Demand-based staffing and productivity", "children": [{"id": "4d387b34-a54f-47fd-8114-6238e3e7d85b", "type": "concept", "title": "Rooms cleaned per hour, covers per labor hour, labor hours per occupied room, revenue per labor hour, and labor cost percentage"}, {"id": "ff4b54b2-95c3-48ba-b6fe-70a1805d67dc", "type": "concept", "title": "Workload standards, staffing curves, minimum crews, skill mix, break coverage, on-call labor, and schedule stability"}, {"id": "b294da75-e9b1-45e9-8994-e2d1fec89f08", "type": "concept", "title": "Fixed and variable labor, learning curves, cross-training, automation, capacity, queues, and service quality"}], "description": "This subtopic converts forecasts and service standards into hours, positions, schedules, and financial expectations."}, {"id": "a081429a-2300-418b-b869-35e18cc761a0", "type": "subtopic", "title": "Labor variances and responsible decisions", "children": [{"id": "13ba8ac4-256d-4393-9969-3d922ba17935", "type": "concept", "title": "Rate, efficiency, overtime, headcount, vacancy, agency, turnover, productivity, and schedule adherence variances"}, {"id": "c50cd9d9-8a3a-4a61-bc81-b06dd7a5a82a", "type": "concept", "title": "Wage changes, mix, volume, absenteeism, training, equipment, layout, rework, quality failures, and demand error"}, {"id": "2a0b5d66-3299-42ee-9aaa-55d92e4d3e48", "type": "concept", "title": "False economy, burnout, injury, wage-and-hour compliance, employee voice, retention value, and balanced measures"}], "description": "Students investigate rate and efficiency differences while considering safety, law, retention, inclusion, and guest outcomes."}]}, {"id": "5aa80d80-c63f-4f72-8a09-e4038fd37e03", "type": "topic", "title": "Rooms, Other Departments, and Property-Level Performance", "description": "Lodging performance must be read from market demand through departmental profit to property-level cash generation. Students learn how metrics interact and why a favorable top-line result can coexist with weak flow-through or owner return.", "children": [{"id": "9bd87ca6-5be1-4cc2-b8b8-294471da6eb2", "type": "subtopic", "title": "Rooms revenue and channel economics", "children": [{"id": "b576662b-d7e4-48c2-938e-f1e4597267b5", "type": "concept", "title": "Available rooms, sold rooms, occupancy, ADR, RevPAR, room nights, length of stay, and booking window"}, {"id": "90f4c60d-0a82-4b90-9ebe-842a1bb81498", "type": "concept", "title": "Direct, brand, GDS, OTA, wholesale, group, negotiated, package, and loyalty channels"}, {"id": "f0d24474-5494-4555-8eac-d8003294b363", "type": "concept", "title": "Gross versus net revenue, commissions, transaction fees, acquisition cost, cancellation, no-show, and displacement"}], "description": "Students analyze rate and volume while accounting for distribution, loyalty, commissions, cancellations, and room-type mix."}, {"id": "783674f1-0b0c-47d1-9b28-7b9742924149", "type": "subtopic", "title": "Departmental and undistributed performance", "children": [{"id": "2fd75f4e-1ca5-4ec9-b72b-6c11b5a00e8a", "type": "concept", "title": "Departmental revenues, cost of sales, payroll, other expenses, and departmental profit/margin"}, {"id": "937da209-f809-4201-a041-ba63add45bd2", "type": "concept", "title": "Housekeeping cost per occupied room, reservation cost, laundry, amenities, utilities, repairs, IT, sales, and administration"}, {"id": "f9734c43-edf0-480e-8759-38cbd26b92d3", "type": "concept", "title": "Flow-through, flex, incremental margin, efficiency, mix, service quality, and maintenance tradeoffs"}], "description": "This subtopic links operational drivers to rooms, F&B, other departments, and shared property costs."}, {"id": "63476706-c8f8-4a2e-a89b-a236cf7e0b6e", "type": "subtopic", "title": "Property, owner, and asset perspectives", "children": [{"id": "0f5fc071-4109-4eaa-8574-d1173165b3dc", "type": "concept", "title": "Gross operating profit, management fees, insurance, property taxes, rent, reserve, interest, depreciation, and owner items"}, {"id": "5586a36e-96d2-4e04-a999-0749f96e1cff", "type": "concept", "title": "GOPPAR, TRevPAR, EBITDA-related measures, cash available, debt-service awareness, and covenant context"}, {"id": "43d54d48-28bd-4bea-b6c2-e8b1fc0cfa2b", "type": "concept", "title": "Management-contract definitions, performance tests, owner/operator adjustments, comparability, and reconciliation"}], "description": "Students reconcile operator measures with management fees, fixed charges, capital needs, and owner economics."}]}, {"id": "a5be5902-d2a1-4ae8-ba53-cea9bf25bcc1", "type": "topic", "title": "Relevant Costs and Short-Run Operating Decisions", "description": "Many managerial choices concern the future cash flows that differ among alternatives. Students learn to exclude sunk and unavoidable amounts, identify opportunity cost and constraints, and present both quantitative and qualitative consequences.", "children": [{"id": "db1b01f5-bb03-4ca9-8c9d-3c9b18ad69d9", "type": "subtopic", "title": "Relevant-cost framework", "children": [{"id": "22fe6b40-5b81-4be2-8e1f-c168fe109db0", "type": "concept", "title": "Relevant, irrelevant, sunk, avoidable, incremental, differential, committed, and opportunity costs"}, {"id": "0d95f931-be44-4eae-90d6-48161a6be361", "type": "concept", "title": "Traceable fixed costs, allocated common costs, cash versus noncash items, taxes, and working capital"}, {"id": "112e771d-76c4-4ba9-93ee-c7c932f5fa46", "type": "concept", "title": "Quantitative model, qualitative factors, stakeholders, reversibility, uncertainty, and decision rights"}], "description": "Students structure a decision around alternatives, time horizon, incremental cash flows, capacity, risks, and strategic effects."}, {"id": "9dafc62e-d708-44e1-9877-ba4446e9999f", "type": "subtopic", "title": "Recurring hospitality decisions", "children": [{"id": "07cb7e6d-e3de-4941-a93c-c383c18a743a", "type": "concept", "title": "Special orders, groups, packages, discounts, upgrades, promotions, minimum guarantees, and displacement"}, {"id": "916a7cac-2700-42b4-88e7-72b62f8fe790", "type": "concept", "title": "Make or buy, outsource, insource, lease or service, centralize or decentralize, repair or replace, and technology vendors"}, {"id": "f09d4c1e-d862-48f6-aa1d-2ef6961e5710", "type": "concept", "title": "Keep or drop an outlet, menu item, service, amenity, shift, channel, customer, event, or property segment"}], "description": "This subtopic applies the framework to choices managers routinely face across lodging, foodservice, and events."}, {"id": "1eeae016-14f5-415d-ad92-23df9b30bedb", "type": "subtopic", "title": "Constraints and optimization", "children": [{"id": "d36c4a8d-7660-4d62-ac27-a4f006f49358", "type": "concept", "title": "Contribution per constrained resource, bottlenecks, throughput, shadow cost, and unused capacity"}, {"id": "1b58ad0e-16a4-41d3-85ab-da434a7a0c5d", "type": "concept", "title": "Product or customer mix, minimum commitments, quality constraints, sequencing, and demand uncertainty"}, {"id": "81c8ed9b-e812-48c9-b365-c2031bb65e12", "type": "concept", "title": "Integer decisions, solver models, sensitivity, implementation feasibility, and ethical guardrails"}], "description": "Students prioritize scarce rooms, seats, labor, kitchen time, event space, equipment, or capital based on contribution and strategic fit."}]}, {"id": "0ba1894e-1f3a-4695-a93d-f1ac7f79ac05", "type": "topic", "title": "Pricing, Revenue Management, and Customer/Channel Profitability", "description": "Price is both a financial lever and a promise to the guest. This section combines cost information with demand, competition, capacity, channel economics, and lifetime value without treating cost-plus pricing as the only answer.", "children": [{"id": "07af3347-f008-455b-84f6-17cc21ae2ad5", "type": "subtopic", "title": "Pricing foundations", "children": [{"id": "79b96ee8-e7ac-48ac-9e9e-086199b506fd", "type": "concept", "title": "Cost-plus, target return, value-based, competitive, dynamic, package, subscription, membership, and promotional pricing"}, {"id": "e354dd25-e352-4aeb-b338-b5b6fedd4dde", "type": "concept", "title": "Floor price, full cost, incremental cost, willingness to pay, elasticity, reference price, and fairness"}, {"id": "d004052c-1b70-493f-ae0b-e42a87ef1b42", "type": "concept", "title": "Rate fences, versioning, bundles, discounts, service charges, resort fees, taxes, and transparent disclosure"}], "description": "Students compare cost, market, value, demand, and strategic approaches and identify what each can and cannot reveal."}, {"id": "a9052e8e-5238-4523-9e39-0f795d86b35a", "type": "subtopic", "title": "Revenue-management economics", "children": [{"id": "4a9d2cc8-cde9-4225-9c90-b24fc48f87fd", "type": "concept", "title": "Demand forecast, unconstrained demand, price, availability, length-of-stay controls, overbooking, and cancellations"}, {"id": "e8f32557-ee2c-4c07-8f44-b8c7c1e65423", "type": "concept", "title": "Group displacement, function-space opportunity, transient versus group, ancillary spend, and total revenue"}, {"id": "e443eb37-91ff-4d99-ba6b-e2682a62aebe", "type": "concept", "title": "ADR, occupancy, RevPAR, contribution RevPAR, TRevPAR, forecast error, and override governance"}], "description": "This subtopic connects perishable capacity to forecasting, inventory controls, displacement, and total contribution."}, {"id": "28c5f0f1-c770-4c7c-89f7-6a435d46e31c", "type": "subtopic", "title": "Customer, segment, product, and channel profitability", "children": [{"id": "46762957-9a7b-415d-89cb-d4043ef6f031", "type": "concept", "title": "Direct product and service costs, order and support activities, acquisition, loyalty, returns, complaints, and bad debt"}, {"id": "a473c264-8124-4e3d-bd4b-e5351ee0160f", "type": "concept", "title": "Customer, group, corporate account, membership, event, menu item, channel, and cohort contribution"}, {"id": "3b4c2652-0979-4a60-8053-ba8c6c6e63e8", "type": "concept", "title": "Lifetime value, retention, incremental behavior, cannibalization, attribution, data limits, privacy, and fairness"}], "description": "Students look beyond revenue to the resources, discounts, commissions, service requirements, and retention economics associated with different demand."}]}, {"id": "fbf45f9b-d697-4765-a996-c444d44b55f2", "type": "topic", "title": "Responsibility Accounting, Performance Measurement, and Dashboards", "description": "Performance systems shape attention and behavior. Students learn to assign accountability only where managers have influence, combine financial and nonfinancial measures, and build dashboards that lead to action rather than data theater.", "children": [{"id": "fbf66cc1-96e4-46cf-9883-7851dd5101b5", "type": "subtopic", "title": "Responsibility centers and controllability", "children": [{"id": "cfdafce7-f53e-45a4-a727-2a5892bc1416", "type": "concept", "title": "Revenue, cost, profit, and investment centers; property, department, outlet, cluster, and corporate roles"}, {"id": "583e5dd8-1c9a-4d8a-a6fe-b3f19e1891a1", "type": "concept", "title": "Controllable versus noncontrollable items, direct versus allocated cost, shared services, and influence"}, {"id": "e588a0f5-fd8d-4254-86ea-cc76b736a430", "type": "concept", "title": "Transfer prices, service-level agreements, internal charges, goal congruence, and disputes"}], "description": "Students align decision authority, resources, measures, and evaluation across the organization."}, {"id": "f9e0f2d0-7818-4f21-8b70-398d2288cbfa", "type": "subtopic", "title": "Financial and operating performance measures", "children": [{"id": "bf4cbda5-fc8c-421c-9c0d-f1da8b58627d", "type": "concept", "title": "Margin, flow-through, ROI, residual income, economic profit, asset turnover, and cash measures"}, {"id": "fd93c7c2-6fcb-43d6-9e04-e65df21079e8", "type": "concept", "title": "Guest satisfaction, quality, complaints, loyalty, employee retention, safety, productivity, accessibility, and sustainability"}, {"id": "947d7a52-1740-4d68-b0f7-472d8d65573a", "type": "concept", "title": "Targets, benchmarks, trends, seasonality, thresholds, confidence, materiality, and unintended incentives"}], "description": "This subtopic selects a balanced set of leading and lagging indicators connected to strategy and controllable drivers."}, {"id": "8c073d52-9ded-4c6f-8afd-e0191a709c55", "type": "subtopic", "title": "Dashboard and review design", "children": [{"id": "037ce29a-d739-4bd8-96f1-5090558cc510", "type": "concept", "title": "Audience, decision, metric dictionary, grain, source, refresh, target, visualization, and accessibility"}, {"id": "586f1942-4fe5-4a0a-a66e-2ea1f982466b", "type": "concept", "title": "Exception reporting, drill-down, annotations, commentary, forecast, actions, owners, due dates, and benefits"}, {"id": "a0988b98-52c9-4041-8f2d-ca71aa8aa79e", "type": "concept", "title": "Daily flash, weekly operations, monthly close, quarterly owner review, and post-investment review"}], "description": "Students turn metrics into a governance routine with definitions, owners, investigation, action, and follow-through."}]}, {"id": "06d4ed00-0b69-41ff-b958-0e4539877e87", "type": "topic", "title": "Capital Budgeting, Cash Flow, Risk, and Investment Decisions", "description": "Hospitality capital decisions affect guest experience, safety, brand compliance, efficiency, resilience, and asset value for years. Students learn to model incremental after-tax cash flows, compare methods, and make uncertainty visible.", "children": [{"id": "d6152aac-150f-48c5-bc47-ea4863160e24", "type": "subtopic", "title": "Project cash-flow construction", "children": [{"id": "0a4ee610-8bd7-4ced-b4e0-d8e320e5f86c", "type": "concept", "title": "Initial outlay, installation, training, downtime, working capital, maintenance, operating savings, revenue effects, and terminal value"}, {"id": "dfb99adc-7b66-4503-95e5-5ca625780056", "type": "concept", "title": "Depreciation tax shield, after-tax cash flow, cannibalization, opportunity cost, allocated overhead, and financing separation"}, {"id": "5a3b025a-d2e6-46bb-9f71-aa4dfdac44b8", "type": "concept", "title": "Renovations, equipment, guestrooms, kitchens, technology, energy projects, accessibility, safety, and mandated capital"}], "description": "Students separate project economics from accounting profit and include all incremental consequences of the decision."}, {"id": "85f316bf-7290-4254-9ef8-38c92a870798", "type": "subtopic", "title": "Investment evaluation methods", "children": [{"id": "f181e452-90ec-4ee7-9dd6-e267083d922e", "type": "concept", "title": "Net present value, internal rate of return, modified IRR, profitability index, payback, discounted payback, and accounting return"}, {"id": "f8656bb7-9997-4eaf-803d-8aa15456a077", "type": "concept", "title": "Discount rate, required return, project life, replacement chains, mutually exclusive projects, and capital rationing"}, {"id": "d0a45faf-37ce-4fc1-a935-19c256077022", "type": "concept", "title": "Spreadsheet functions, timeline consistency, sign conventions, rounding, audit checks, and interpretation"}], "description": "This subtopic compares decision measures and explains when they may rank projects differently."}, {"id": "3cc8e0d9-94ec-4ca5-b3e2-3bbe88bbfdb4", "type": "subtopic", "title": "Risk, scenario, and post-audit", "children": [{"id": "165d2c7c-6782-4375-981f-b7e0c9483056", "type": "concept", "title": "Sensitivity, scenario, break-even, decision tree, simulation concepts, real options, and risk-adjusted discount rates"}, {"id": "f2dcf0cb-e738-47ce-9d03-7bcd159e4749", "type": "concept", "title": "Demand, rate, cost, schedule, technology, construction, regulatory, climate, and execution risks"}, {"id": "e60ff11f-b1a1-4ff7-a15e-8cf5175776ff", "type": "concept", "title": "Stage gates, contingencies, approval, benefits owner, baseline, post-completion review, lessons, and corrective action"}], "description": "Students evaluate uncertainty explicitly and establish how management will learn whether promised benefits occurred."}]}, {"id": "1036b366-b1fd-4a5f-87e2-7b4dd4e0898a", "type": "topic", "title": "Internal Controls, Accounting Systems, Analytics, AI, and Sustainability", "description": "Reliable decisions require trustworthy processes, data, models, and controls. The final section integrates transaction cycles, analytics, automation, responsible AI, and sustainability accounting into a modern management-control system.", "children": [{"id": "f6aab6aa-3a35-40e7-84bf-99f4c167322d", "type": "subtopic", "title": "Internal control and transaction cycles", "children": [{"id": "36247fdb-5bee-44c1-b13d-3c903c014512", "type": "concept", "title": "COSO objectives and components; authorization, segregation, documentation, custody, reconciliation, review, and monitoring"}, {"id": "9b3c498a-8d3f-4af5-9a30-5ff4e57ae6ab", "type": "concept", "title": "Revenue, cash, cards, receivables, purchasing, receiving, inventory, payroll, tips, fixed assets, and journal entries"}, {"id": "97f32627-bf7e-4f82-8394-ea3451729460", "type": "concept", "title": "Fraud risks, overrides, comps, voids, refunds, chargebacks, vendor schemes, time theft, cyber incidents, and whistleblowing"}], "description": "Students apply preventive and detective controls to the high-volume, decentralized, cash- and data-intensive hospitality environment."}, {"id": "7415cdea-e160-43ed-9efd-9e005189c03d", "type": "subtopic", "title": "Systems, data, models, and responsible AI", "children": [{"id": "0ef5d842-44c0-415a-94be-4a6487d35a18", "type": "concept", "title": "Source systems, interfaces, chart-of-accounts mapping, master data, close calendar, data lineage, and reconciliation"}, {"id": "4453befc-7795-499d-8ebd-f34b68915fe7", "type": "concept", "title": "Spreadsheet controls, input/output separation, formulas, versioning, access, review, documentation, and model risk"}, {"id": "db1f03e9-4fa8-45f0-9e64-f61c77172331", "type": "concept", "title": "Predictive forecasts, anomaly detection, generative AI, privacy, bias, hallucination, explainability, human review, and audit trail"}], "description": "This subtopic connects PMS, POS, labor, procurement, CRM, RMS, ERP, and BI data to reproducible managerial analysis."}, {"id": "ba12a237-96b8-4b52-bae6-c8466f7de80e", "type": "subtopic", "title": "Sustainability and strategic cost management", "children": [{"id": "00114f7c-5ad9-4719-83f6-552fcfbaeabb", "type": "concept", "title": "Energy, water, waste, food loss, carbon, laundry, chemicals, sourcing, safety, turnover, and community impacts"}, {"id": "43d692b3-9ac4-4597-87b2-ceb0fbb705c4", "type": "concept", "title": "Physical and transition risk, life-cycle cost, total cost of ownership, carbon pricing scenarios, and resilience investment"}, {"id": "746af843-22b7-4931-8fe4-695668f42ff1", "type": "concept", "title": "Relevant boundary, baseline, allocation, intensity metrics, avoided cost, rebound effects, assurance, green claims, and balanced decisions"}], "description": "Students measure environmental and social drivers where they affect cost, risk, revenue, people, and long-term asset performance."}]}], "dbBacked": true}$hmacjson$::jsonb,
